module parallel2serial(
    input clk, 
    input rst_n, 
    input [3:0] d,
    output valid_out, 
    output dout
);
// Sequential logic for counter and data storage
reg [1:0] cnt;
reg [3:0] data;
reg valid;
// Assign dout to the MSB of the data register
assign dout = data[3];
// Assign valid_out to the valid register
assign valid_out = valid;
// Always block triggered on the positive edge of the clock or negative edge of the reset signal
always @(posedge clk or negedge rst_n) begin
    // Check if the reset signal is low
    if (~rst_n) begin
        // Reset the counter to 0
        cnt <= 2'd0;

        // Reset the data register to 0
        data <= 4'd0;

        // Set the valid register to 0
        valid <= 1'b0;
    end else begin
        // Check if the counter has reached 3
        if (cnt == 2'd3) begin
            // Load the new input data into the data register
            data <= d;

            // Reset the counter to 0
            cnt <= 2'd0;

            // Set the valid register to 1
            valid <= 1'b1;
        end else begin
            // Rotate the data register to the left by 1 bit
            data <= {data[2:0], data[3]};

            // Increment the counter by 1
            cnt <= cnt + 1;

            // Set the valid register to 0
            valid <= 1'b0;
        end
    end
end
endmodule
